// Interface language. /locale.js (generated by the app from locales/<code>.json)
// defines window.I18N = {language, languages, messages}, where messages maps the
// Russian source text to its translation. Loaded before every other script.
//
// - t(text, params) translates strings built in scripts ("{name}" placeholders).
// - Static HTML is translated once below; text and title/placeholder attributes
//   that scripts insert later are translated by a MutationObserver when they
//   match a dictionary entry exactly.
// - Elements with translate="no" (project names, phrases, logs) are left alone.

const I18N_STATE = window.I18N || { language: "ru", languages: ["ru"], messages: {} };
const UI_LANGUAGE = I18N_STATE.language || "ru";
const I18N_MESSAGES = I18N_STATE.messages || {};
const I18N_ATTRIBUTES = ["placeholder", "title", "aria-label"];
const LANGUAGE_SELF_NAMES = {
  ru: "Русский", en: "English", uk: "Українська", de: "Deutsch", es: "Español", fr: "Français",
  it: "Italiano", pt: "Português", pl: "Polski", tr: "Türkçe", ja: "日本語", ko: "한국어", zh: "中文",
};

function hasMessage(key) {
  return Object.prototype.hasOwnProperty.call(I18N_MESSAGES, key);
}

function t(text, params) {
  let result = hasMessage(text) ? I18N_MESSAGES[text] : text;
  if (params) {
    result = result.replace(/\{(\w+)\}/g, (match, key) => (key in params ? String(params[key]) : match));
  }
  return result;
}

function translatedText(value) {
  const key = value.replace(/\s+/g, " ").trim();
  if (!key || !hasMessage(key)) return null;
  return value.match(/^\s*/)[0] + I18N_MESSAGES[key] + value.match(/\s*$/)[0];
}

function untranslatable(element) {
  return !element || Boolean(element.closest("[translate='no'], script, style"));
}

function translateTextNode(node) {
  // A textarea's text is what the user typed; only its placeholder is ours.
  if (untranslatable(node.parentElement) || node.parentElement.tagName === "TEXTAREA") return;
  const value = translatedText(node.nodeValue);
  if (value !== null && value !== node.nodeValue) node.nodeValue = value;
}

function translateAttributes(element) {
  if (untranslatable(element)) return;
  for (const name of I18N_ATTRIBUTES) {
    const current = element.getAttribute(name);
    if (!current) continue;
    const value = translatedText(current);
    if (value !== null && value !== current) element.setAttribute(name, value);
  }
}

function translateTree(root) {
  if (root.nodeType === Node.TEXT_NODE) {
    translateTextNode(root);
    return;
  }
  if (root.nodeType !== Node.ELEMENT_NODE || untranslatable(root)) return;
  translateAttributes(root);
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT, {
    acceptNode: (node) => (node.nodeType === Node.ELEMENT_NODE && node.matches("[translate='no'], script, style")
      ? NodeFilter.FILTER_REJECT
      : NodeFilter.FILTER_ACCEPT),
  });
  for (let node = walker.nextNode(); node; node = walker.nextNode()) {
    if (node.nodeType === Node.TEXT_NODE) translateTextNode(node);
    else translateAttributes(node);
  }
}

document.documentElement.lang = UI_LANGUAGE;
if (Object.keys(I18N_MESSAGES).length) {
  translateTree(document.body);
  new MutationObserver((mutations) => {
    for (const mutation of mutations) {
      if (mutation.type === "characterData") translateTextNode(mutation.target);
      else if (mutation.type === "attributes") translateAttributes(mutation.target);
      else for (const node of mutation.addedNodes) translateTree(node);
    }
  }).observe(document.body, {
    subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: I18N_ATTRIBUTES,
  });
}

// Language switch in the side rail: saved in the app settings, applied on reload.
const uiLanguageSelect = document.getElementById("uiLanguage");
if (uiLanguageSelect) {
  for (const code of I18N_STATE.languages || ["ru"]) {
    const option = document.createElement("option");
    option.value = code;
    option.textContent = LANGUAGE_SELF_NAMES[code] || code.toUpperCase();
    uiLanguageSelect.appendChild(option);
  }
  uiLanguageSelect.value = UI_LANGUAGE;
  uiLanguageSelect.hidden = uiLanguageSelect.options.length < 2;
  uiLanguageSelect.addEventListener("change", async () => {
    await fetch("/api/settings", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ ui: { language: uiLanguageSelect.value } }),
    });
    window.location.reload();
  });
}
